"use client";

import { useState } from "react";

export default function Home() {
  const [input, setInput] = useState("");
  const [result, setResult] = useState([]);

  const onSubmit = async () => {
    const res = await fetch("/api/plan", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ input }),
    }); //sent data called input

    const data = await res.json(); //receiving the response from the backend and parsing it as JSON
    console.log(data.reasoning);
    setResult(data.results);
  };

  return (
    <div className="p-8 h-screen flex flex-col items-center">
      <div className="text-3xl font-bold text-gray-900 flex bg-amber-200 w-full">
        <h1 className="bg-amber-500 w-fit py-3 px-6 rounded-xl">trAI</h1>
      </div>

      <div className="bg-amber-100 max-w-[70%] w-full mt-10 p-6 rounded-lg shadow">
        <input
          type="text"
          className="border border-gray-300 rounded w-full p-3 mb-4 focus:outline-none focus:border-blue-500"
          onChange={(e) => setInput(e.target.value)}
          placeholder="Describe your journey..."
        />

        <button className="bg-blue-600 text-white w-full p-3 rounded font-medium hover:bg-blue-700 transition"
        onClick={onSubmit}>
          Submit
        </button>

        {result.length > 0 && (
          <div className="mt-8 space-y-3">
            {result.map((journey, index) => (
              <div
                key={index}
                className="border rounded-lg p-4 mb-4 bg-white shadow-sm"
              >
                {/* Train Name */}
                <h3 className="text-lg font-semibold">{journey.train}</h3>

                {/* Quick facts */}
                <div className="text-sm text-gray-600 mt-1 flex gap-3">
                  <span>{journey.durationHours} hrs</span>
                  <span>₹{journey.price}</span>
                  <span>{journey.comfort}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
